// Package moj 讀取法務部「全國法規資料庫」公開資料（FalV.xml / MingLing.xml），
// 將法規與條文轉成結構化資料，供後續切塊與向量化使用。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 以官方開放資料為唯一權威來源，避免手工整理法條造成版本漂移
package moj

import "strings"

// Nature 表示法規性質（法律 / 命令），對應 XML 的 <法規性質>。
type Nature string

const (
	// NatureLaw 為「法律」（立法院三讀通過之法）。
	NatureLaw Nature = "法律"
	// NatureOrder 為「命令」（規則、辦法、規程等）。
	NatureOrder Nature = "命令"
)

// Law 為一部法規及其全部條文；欄位對齊全國法規資料庫公開資料欄位。
type Law struct {
	Nature      Nature    `json:"nature"`
	Name        string    `json:"name"`
	PCode       string    `json:"pcode"`
	SourceURL   string    `json:"source_url"`
	Category    string    `json:"category"`
	UpdatedAt   string    `json:"updated_at"` // YYYYMMDD
	Effective   string    `json:"effective_at,omitempty"`
	Repealed    bool      `json:"repealed"`
	EnglishName string    `json:"english_name,omitempty"`
	History     string    `json:"history,omitempty"`
	Preamble    string    `json:"preamble,omitempty"`
	Articles    []Article `json:"articles"`
}

// Article 為單一條文；Chapter 為該條所屬之編章節標題（可能為空）。
type Article struct {
	No      string `json:"no"`      // 正規化條號，如 "1"、"87-1"
	Label   string `json:"label"`   // 顯示用，如 "第 87-1 條"
	Chapter string `json:"chapter"` // 如 "第一章 總則"
	Content string `json:"content"`
}

// Filter 決定哪些法規要被保留；類別前綴或名稱任一相符即保留，兩者皆空時保留全部。
type Filter struct {
	CategoryPrefixes []string // 法規類別前綴，如 "立法"
	Names            []string // 法規名稱完全相符
	ExcludeRepealed  bool
}

// Match 回報 law 是否符合過濾條件。
//
// @ai:generated by=claude-fable-5-1 date=2026-10-09
// @ai:purpose 讓 parser 在串流階段就丟棄無關法規，避免 112MB XML 全量進記憶體
// @ai:input law 法規
// @ai:output 是否保留
// @ai:sideeffect none
func (f Filter) Match(law *Law) bool {
	if f.ExcludeRepealed && law.Repealed {
		return false
	}
	if len(f.CategoryPrefixes) == 0 && len(f.Names) == 0 {
		return true
	}
	for _, p := range f.CategoryPrefixes {
		if p != "" && strings.HasPrefix(law.Category, p) {
			return true
		}
	}
	for _, n := range f.Names {
		if n != "" && law.Name == n {
			return true
		}
	}
	return false
}
